import java.util.concurrent.locks.ReentrantLock;

public class PinningMitigationService {
    // BAD: Using synchronized causes virtual thread pinning on the carrier
    private final Object legacyMonitor = new Object();

    public void legacySynchronizedMethod() {
        synchronized (legacyMonitor) {
            // If this blocks on I/O, the underlying OS carrier thread is pinned!
            doBlockingOperation();
        }
    }

    // GOOD: ReentrantLock allows virtual threads to cleanly unmount when blocked
    private final ReentrantLock modernLock = new ReentrantLock();

    public void safeLockMethod() {
        modernLock.lock();
        try {
            // Virtual thread unmounts cleanly here if blocked on I/O
            doBlockingOperation();
        } finally {
            modernLock.unlock();
        }
    }

    private void doBlockingOperation() {
        // Simulated blocking I/O or database call
    }
}
